sealed class Hero:Control {
 Image art;
 public Hero(){DoubleBuffered=true;var stream=typeof(Hero).Assembly.GetManifestResourceStream("LauncherArt");if(stream!=null){using(stream)using(var original=Image.FromStream(stream))art=new Bitmap(original);}}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;if(art!=null){float scale=Math.Max((float)Width/art.Width,(float)Height/art.Height);float w=art.Width*scale,h=art.Height*scale;g.DrawImage(art,(Width-w)/2,(Height-h)/2,w,h);}using(var shade=new LinearGradientBrush(ClientRectangle,Color.FromArgb(5,12,17,16),Color.FromArgb(245,12,17,16),90))g.FillRectangle(shade,ClientRectangle);DrawMark(g,30,Height-139,70);using(var title=new Font("Georgia",28,FontStyle.Bold))using(var sub=new Font("Segoe UI",10,FontStyle.Bold)){g.DrawString("ASHEN MEADOW",title,Brushes.Ivory,114,Height-131);using(var brush=new SolidBrush(Color.FromArgb(223,178,100)))g.DrawString("E X P E D I T I O N   /   P L A Y T E S T",sub,brush,118,Height-80);}}
 public static void DrawMark(Graphics g,int x,int y,int size){g.SmoothingMode=SmoothingMode.AntiAlias;using(var p=new Pen(Color.FromArgb(223,178,100),2)){g.DrawEllipse(p,x,y,size,size);g.DrawArc(p,x+size/4,y+size/5,size/2,size/2,180,180);for(int i=0;i<5;i++){int px=x+size/4+i*size/8;g.DrawLine(p,px,y+size*3/4,px+3,y+size/2-i%2*8);g.DrawLine(p,px+3,y+size/2,px-3,y+size/2-5);}g.DrawLine(p,x+size/5,y+size*3/4,x+size*4/5,y+size*3/4);}}
 protected override void Dispose(bool disposing){if(disposing&&art!=null)art.Dispose();base.Dispose(disposing);}
}

sealed class Launcher:Form {
 readonly Label status=new Label(),notes=new Label(),location=new Label();readonly TextBox address=new TextBox();readonly Button update=new Button(),play=new Button(),browse=new Button();readonly ProgressBar progress=new ProgressBar();Installer installer;Feed available;Process game;bool busy;readonly string configPath;readonly string defaultRoot;
 static readonly Color Gold=Color.FromArgb(223,178,100);
 public Launcher(bool preview){Text="Ashen Meadow | Expedition";Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);ClientSize=new Size(820,660);AutoScaleMode=AutoScaleMode.Dpi;BackColor=Color.FromArgb(12,17,16);ForeColor=Color.FromArgb(232,232,217);Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedSingle;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;
 defaultRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AshenMeadow","GodotPlaytest");configPath=Path.Combine(defaultRoot,"launcher.json");Settings settings=new Settings{Repository="benediktpetur/Ashen-Medows"};try{string p=File.Exists(configPath)?configPath:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher.json");if(File.Exists(p))settings=Data.Read<Settings>(File.ReadAllText(p));}catch{}
 try{installer=new Installer(string.IsNullOrWhiteSpace(settings.InstallRoot)?defaultRoot:settings.InstallRoot);}catch{installer=new Installer(defaultRoot);}
 var hero=new Hero();hero.SetBounds(0,0,820,300);Controls.Add(hero);
 AddLabel("UPDATE SOURCE",30,311,760,20,Gold);address.SetBounds(30,336,760,28);address.BackColor=Color.FromArgb(25,33,29);address.ForeColor=ForeColor;address.BorderStyle=BorderStyle.FixedSingle;address.Text=string.IsNullOrWhiteSpace(settings.Repository)?settings.ManifestUrl:settings.Repository;Controls.Add(address);
 AddLabel("GAME INSTALL FOLDER",30,379,600,20,Gold);location.SetBounds(30,405,620,35);location.AutoEllipsis=true;Controls.Add(location);browse.Text="CHOOSE...";browse.SetBounds(666,400,124,34);Style(browse,false);browse.Click+=(s,e)=>ChooseFolder();Controls.Add(browse);
 status.SetBounds(30,453,760,28);Controls.Add(status);notes.SetBounds(30,485,760,52);notes.ForeColor=Color.FromArgb(163,177,164);Controls.Add(notes);progress.SetBounds(30,549,760,8);Controls.Add(progress);
 update.Text="CHECK / UPDATE";update.SetBounds(30,577,300,49);Style(update,false);update.Click+=async(s,e)=>await UpdateGame();Controls.Add(update);play.Text="PLAY EXPEDITION";play.SetBounds(346,577,444,49);Style(play,true);play.Click+=(s,e)=>Play();Controls.Add(play);
 RefreshInstalled();if(!preview)Shown+=async(s,e)=>{if(address.Text.Length>0&&installer.Current()!=null)await UpdateGame();};FormClosing+=(s,e)=>{if(busy){e.Cancel=true;status.Text="Please let the current update finish before closing.";}};
 }
 void AddLabel(string text,int x,int y,int w,int h,Color color){Controls.Add(new Label{Text=text,Left=x,Top=y,Width=w,Height=h,ForeColor=color,Font=new Font("Segoe UI",9,FontStyle.Bold)});}
 void Style(Button b,bool primary){b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Color.FromArgb(73,85,69);b.BackColor=primary?Gold:Color.FromArgb(25,33,29);b.ForeColor=primary?Color.FromArgb(12,17,16):ForeColor;b.Font=new Font("Segoe UI",10,FontStyle.Bold);b.Cursor=Cursors.Hand;}
 void SaveSettings(){Directory.CreateDirectory(defaultRoot);Data.Atomic(configPath,Data.Write(new Settings{Repository=address.Text.Trim(),InstallRoot=installer.Root}));}
 void ChooseFolder(){if(busy||Running()){status.Text="Close the game before changing its install folder.";return;}using(var dialog=new FolderBrowserDialog{Description="Choose where Ashen Meadow downloads and installs its game builds. Existing installs stay in their original folder; selecting that folder again restores access.",SelectedPath=installer.Root,ShowNewFolderButton=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;var old=installer;try{installer=new Installer(dialog.SelectedPath);SaveSettings();RefreshInstalled();notes.Text="Folder saved. Check / Update installs here. Previous downloads stay in their original folder; your Godot character save is unchanged.";}catch(Exception ex){installer=old;RefreshInstalled();notes.Text="Could not use that folder: "+ex.Message;}}}
 void RefreshInstalled(){location.Text=installer.Root;var f=installer.Current();play.Enabled=!busy&&f!=null&&File.Exists(installer.GamePath(f));status.Text=play.Enabled?"Installed version "+f.Version+" / playable offline":"No game installed in this folder. Check / Update to download.";}
 bool Running(){try{return game!=null&&!game.HasExited;}catch{return false;}}
 async Task UpdateGame(){if(busy)return;Uri uri;try{uri=new Uri(GitHubFeed.Resolve(address.Text));}catch(Exception ex){status.Text=ex.Message;return;}if(Running()){status.Text="Close the game before installing an update.";return;}busy=true;update.Enabled=play.Enabled=address.Enabled=browse.Enabled=false;string zip=Path.Combine(installer.Root,"download-"+Guid.NewGuid().ToString("N")+".zip");try{SaveSettings();ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;status.Text="Checking for updates...";using(var web=new WebClient()){web.Headers[HttpRequestHeader.UserAgent]="AshenMeadowLauncher/1.1";byte[] raw=await web.DownloadDataTaskAsync(uri);if(raw.Length>65536)throw new IOException("Manifest too large.");available=Data.Read<Feed>(Encoding.UTF8.GetString(raw));Installer.Validate(available);GitHubFeed.CheckBuild(uri.AbsoluteUri,available.Url);notes.Text=available.Notes??"";var old=installer.Current();if(old!=null&&new Version(available.Version)<=new Version(old.Version)&&File.Exists(installer.GamePath(old))){status.Text="Installed "+old.Version+" / up to date";return;}status.Text="Downloading "+available.Version+"...";web.DownloadProgressChanged+=(s,e)=>{progress.Value=Math.Max(0,Math.Min(100,e.ProgressPercentage));if(e.BytesReceived>available.Bytes||e.BytesReceived>Installer.Limit)web.CancelAsync();};await web.DownloadFileTaskAsync(new Uri(available.Url),zip);status.Text="Verifying and installing...";await Task.Run(()=>installer.Install(available,zip));status.Text="Ready / version "+available.Version;}}catch(Exception ex){status.Text="Update unavailable. You can still play an installed build.";notes.Text=ex.Message;}finally{if(File.Exists(zip))File.Delete(zip);busy=false;update.Enabled=address.Enabled=browse.Enabled=true;var f=installer.Current();play.Enabled=f!=null&&File.Exists(installer.GamePath(f));progress.Value=0;}}
 void Play(){try{if(Running()){status.Text="The game is already running.";return;}var f=installer.Current();if(f==null)return;var start=new ProcessStartInfo(installer.GamePath(f)){WorkingDirectory=Path.GetDirectoryName(installer.GamePath(f)),UseShellExecute=false};start.EnvironmentVariables["ASHENMEADOW_SAVE_ROOT"]=Path.Combine(defaultRoot,"saves");game=Process.Start(start);status.Text="Running "+f.Version;}catch(Exception ex){status.Text=ex.Message;}}
 [STAThread] static int Main(string[] args){try{if(Array.IndexOf(args,"--check")>=0){LauncherChecks.Run();return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length==2&&args[0]=="--preview"){using(var form=new Launcher(true)){form.Show();Application.DoEvents();using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(Point.Empty,form.Size));bmp.Save(args[1]);}form.Close();}return 0;}bool owned;using(var mutex=new System.Threading.Mutex(true,"Local\\AshenMeadowGodotLauncher",out owned)){if(!owned){MessageBox.Show("The playtest launcher is already open.");return 0;}Application.Run(new Launcher(false));}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher-error.txt"),ex.ToString());return 1;}}
}
